package com.example.starter.asrun;

/**
 * as-run 播出记录视图：半开时段 [startMs, endMs)，endMs 为空表示在播。
 * status：OPEN 在播 / CLOSED 已结束 / SUPERSEDED 被后续记录取代。
 */
public record AsRunRecord(
        String channelId,
        long seq,
        String kind,
        String itemId,
        String mediaDigest,
        String breakRequestId,
        long startMs,
        Long endMs,
        String status,
        boolean acked,
        Long ackedAtMs
) {
}

package com.example.starter.common;

import org.springframework.http.HttpStatus;

/**
 * 业务异常：携带 HTTP 状态码，由全局异常处理器转换为响应。
 */
public class ApiException extends RuntimeException {

    private final HttpStatus status;

    public ApiException(HttpStatus status, String message) {
        super(message);
        this.status = status;
    }

    public HttpStatus status() {
        return status;
    }

    public static ApiException conflict(String message) {
        return new ApiException(HttpStatus.CONFLICT, message);
    }

    public static ApiException notFound(String message) {
        return new ApiException(HttpStatus.NOT_FOUND, message);
    }

    public static ApiException unprocessable(String message) {
        return new ApiException(HttpStatus.UNPROCESSABLE_ENTITY, message);
    }
}

package com.example.starter.common;

import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.http.converter.HttpMessageNotReadableException;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

import java.util.LinkedHashMap;
import java.util.Map;

/**
 * 全局异常处理：业务异常按语义映射状态码，参数校验失败返回 400。
 */
@RestControllerAdvice
public class ApiExceptionHandler {

    @ExceptionHandler(ApiException.class)
    public ResponseEntity<Map<String, Object>> handleApi(ApiException ex) {
        return build(ex.status(), ex.getMessage());
    }

    @ExceptionHandler({MethodArgumentNotValidException.class, HttpMessageNotReadableException.class})
    public ResponseEntity<Map<String, Object>> handleBadRequest(Exception ex) {
        return build(HttpStatus.BAD_REQUEST, "请求参数不合法");
    }

    private ResponseEntity<Map<String, Object>> build(HttpStatus status, String message) {
        Map<String, Object> body = new LinkedHashMap<>();
        body.put("status", status.value());
        body.put("error", status.getReasonPhrase());
        body.put("message", message);
        return ResponseEntity.status(status).body(body);
    }
}

package com.example.starter.adapter;

import com.example.starter.asrun.AsRunRecord;

/**
 * 播出适配器：向（合成的）播出设备发送切换指令。实现不连接真实广电设备。
 */
public interface PlayoutAdapter {

    /**
     * 指定 as-run 记录对应的素材开始播出。
     */
    void onAir(AsRunRecord record);

    /**
     * 指定 as-run 记录对应的素材停止播出。
     */
    void offAir(AsRunRecord record);
}

package com.example.starter.adapter;

import com.example.starter.asrun.AsRunRecord;
import org.springframework.stereotype.Component;

import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;

/**
 * 合成播出适配器：仅记录指令序列，不连接真实设备；测试可读取已发指令。
 */
@Component
public class SyntheticPlayoutAdapter implements PlayoutAdapter {

    /**
     * 已发送指令：格式 "ON#<channel>#<seq>#<mediaDigest>" / "OFF#<channel>#<seq>"。
     */
    private final List<String> commands = new CopyOnWriteArrayList<>();

    @Override
    public void onAir(AsRunRecord record) {
        commands.add("ON#" + record.channelId() + "#" + record.seq() + "#" + record.mediaDigest());
    }

    @Override
    public void offAir(AsRunRecord record) {
        commands.add("OFF#" + record.channelId() + "#" + record.seq());
    }

    public List<String> commands() {
        return List.copyOf(commands);
    }

    public void clear() {
        commands.clear();
    }
}

